const createEval = (inputEds, evalEd, outputEds, asyncOutputEds={}, debounceTime=0, id='DEFAULT', fn=null) => {
  const [workerPool, setWorkerPool] = useState([])

  const evalDeps = inputEds.concat([evalEd]).map(ed => ed.src.val)
  useDebouncedEffect(() => {
    // terminate running workers
    workerPool.forEach(w => w.terminate())

    // spawn new worker
    const evaluator = new Worker(new URL('Eval.js', import.meta.url))
    setWorkerPool([evaluator])

    // flag output eds as in progress
    outputEds.concat(Object.values(asyncOutputEds)).forEach(ed => ed.evaluating.set(true))

    // recv from ww
    evaluator.onmessage = ({data}) => {
      // async output
      if (data?.op == 'async_set') {
        if (asyncOutputEds.hasOwnProperty(data.id)) {
          const ed = asyncOutputEds[data.id]
          const val = data.val
          ed.src.set(val)
          ed.evaluating.set(false)
          ed.error.set(data.error)
        }    
      }

      // sync output
      else {
        const results = data.results
        results.forEach(res => {
          const ed = eds[res.id]
          const val = res.val
          ed.src.set(val)
          ed.evaluating.set(false)
          ed.error.set(res.error)
        })
      }
    }
    
    // send to ww
    const inputsMap = {}
    inputEds.forEach(ed => inputsMap[ed.id] = ed.src.val)
    evaluator.postMessage({
      inputs: inputsMap,
      outputs: outputEds.map(ed => ({id: ed.id})),
      src: evalEd.src.val,
      fn: fn,
    })
  }, evalDeps, debounceTime)
}
const keyboardKey = (control, kDisplay, disabled, kID=null) => {
  // util
  const char2keycode = {
    'a': 65,
    'd': 68,
    's': 83,
    'w': 87,
    ' ': 32,
    'enter': 13,
    'b': 66,
  }

  // empty key
  if (control == null && kDisplay==null && kID==null) {
    return (
      <span className='kbk empty'>
        <code>{'_'}</code>
      </span>
    )
  }

  // state
  const active = makeState(false)

  if (kID == null)
    kID = kDisplay
  const kDisplayUp = kDisplay.toUpperCase()
  const kIDUp = kID.toUpperCase()
  const onMouse = (down, active) => {
    if (disabled)
      return

    active.set(down)
    const keycode = char2keycode[kID]
    log('kID',kID,'keycode',keycode)
    const e = {
      keyCode: keycode,
      type: down ? 'keydown' : 'keyup',
      preventDefault: ()=>{},
    }
    if (window.WOTO_KEY_HANDLER != null)
      window.WOTO_KEY_HANDLER(e)
  }
  return (
    tooltip({
      id: control,
      title: control,
      content: (
        <span
          className={`kbk ${active.val ? 'active' : ''} ${disabled ? 'disabled' : ''}`}
          data-keyboard-key={kIDUp}
          onMouseDown={() => onMouse(true, active)}
          onMouseUp={() => onMouse(false, active)}
        >
          <code>{kDisplayUp}</code>
        </span>
      ),
    })
  )
}

