sCollided/*|| !stationary*/)\n\t\t\t\tcontinue;\n\t\t\tBounds b = GetGroupBounds(g);\n\t\t\tif (b.max.y > boardBounds.max.y)\n\t\t\t\tgs.Add(g);\n\t\t}\n\t\treturn gs.Count > 0;\n\t}\n\tList<Block> GetBlocksAboveBoard(List<Gob> groupsAbove) {\n\t\tList<Block> bs = new();\n\t\tforeach (Gob g in groupsAbove) {\n\t\t\tforeach (Block b in GetBlocksInGroup(g)) {\n\t\t\t\tif (b.gob.BoxCollider2D().bounds.max.y > boardBounds.max.y)\n\t\t\t\t\tbs.Add(b);\n\t\t\t}\n\t\t}\n\t\treturn bs;\n\t}\n\tfloat GetMaxGroupY(bool includeLast=false) {\n\t\tfloat maxY = boardBounds.min.y;\n\t\tList<Block> bs = new();\n\t\tforeach (Gob g in groups) {\n\t\t\tif (g == lastGroup && !includeLast)\n\t\t\t\tcontinue;\n\t\t\tBounds b = GetGroupBounds(g);\n\t\t\tif (b.max.y > maxY)\n\t\t\t\tmaxY = b.max.y;\n\t\t}\n\t\treturn maxY;\n\t}\n\tvoid ShowGameOverPanel(bool newHighScore) {\n\t\tif (newHighScore) {\n\t\t\tgameOverPanel.Child(\"title\").Text().text = \"New Best!\";\n\t\t\treviveHighScore.Child(\"crown\").Child(\"high score\").Text().text = \"\"+Util.GInt(\"highScore\",1);\n\t\t\treviveHighScore.On();\n\t\t\tDo(v3.one*0.5f, v3.one*1.435882f, 0.5f, Motion.SMOOTH, scale => reviveHighScore.transform.localScale = scale);\n\t\t}\n\t\telse {\n\t\t\tfloat completion = (float)score/scoreGoal;\n\t\t\tgameOverPanel.Child(\"title\").Text().text = completion < 0.7f ? \"Keep Going!\" : \"So Close!\";\n\t\t}\n\t\tgameOverPanel.On();\n\t}\n\tSprite LoadItemSprite(string itemName) {\n\t\tTexture2D itemTex = Resources.Load<Texture2D>(\"items/\"+itemName);\n\t\treturn Sprite.Create(itemTex, new Rect(0f, 0f, itemTex.width, itemTex.height), new v2(0.5f,0.5f));\n\t}\n\tvoid LoadGame() {\n\t\tbool gameOver = Util.GBool(\"gameOver\", true);\n\t\tif (gameOver)\n\t\t\treturn;\n\n\t\t// dock\n\t\tstring dockString = Util.GString(\"dock\", \"_,_,_\");\n\t\tlog(dockString);\n\t\tdockItems = dockString.Split(',').ToList();\n\t\tfor (int i = 0; i < dockItems.Count; i++) {\n\t\t\tlog(dockItems[i]);\n\t\t\tif (dockItems[i]