n\t}\n\n\t///////\n\t// INIT\n\t///////\n\tvoid HideTemplates() {\n\t\tblockTemp.Off();\n\t\tgroupTemp.Off();\n\t\tpopTextTemp.Off();\n\t\texplosionTemp.Off();\n\t\twallTemp.Off();\n\t}\n\tvoid HideObjects() {\n\t\t// ui\n\t\trewardedItem.Off();\n\t\tdraggableItem.Off();\n\t\tsettingsPanel.Off();\n\t\tgameOverPanel.Off();\n\t\treviveHighScore.Off();\n\t}\n\tvoid MakeWalls() {\n\t\tfloat bevelBuf = 0.3f;\n\t\tfloat wallThickness = 10f;\n\n\t\tBounds b = board.SpriteRenderer().bounds;\n\t\tb.Expand(-bevelBuf);\n\t\tb.min = new v3(b.min.x, b.min.y, -1f);\n\t\tb.max = new v3(b.max.x, b.max.y, 1f);\n\t\tboardBounds = b;\n\n\t\tGob left = make(wallTemp);\n\t\tleft.On();\n\t\tleft.Pos(board.Pos() + v3.left * (b.extents.x + wallThickness*0.5f));\n\t\tleft.gc<BoxCollider2D>().size = new v2(wallThickness, b.size.y*20f);\n\n\t\tGob right = make(wallTemp);\n\t\tright.On();\n\t\tright.Pos(board.Pos() + v3.right * (b.extents.x + wallThickness*0.5f));\n\t\tright.gc<BoxCollider2D>().size = new v2(wallThickness, b.size.y*20f);\n\n\t\tGob bottom = make(wallTemp);\n\t\tbottom.On();\n\t\tbottom.name = \"floor\";\n\t\tbottom.Pos(board.Pos() + v3.down * (b.extents.y + wallThickness*0.5f));\n\t\tbottom.gc<BoxCollider2D>().size = new v2(b.size.x, wallThickness);\n\t}\n\tvoid Awake() {\n\t\tHideTemplates();\n\t\tHideObjects();\n\t\tMakeWalls();\n\t}\n\tvoid Start() {\n\t\t// cam\n\t\tinitialCamPos = cam.gameObject.Pos();\n\t\t\n\t\t// level start\n\t\tSpawnGroup();\n\n\t\t// base state\n\t\tscore = 0;\n\t\troundIndex = 0;\n\t\tlastHighScore = Util.GInt(\"highScore\", 1);\n\t\talive = true;\n\t\thitHapticTimer = new Timer(0.05f, true);\n\t\tclearHapticTimer = new Timer(0.05f, true);\n\n\t\t// load saved game\n\t\tLoadGame();\n\n\t\t// derived start state\n\t\tscoreGoal = startScoreGoal + scoreGoalIncrement*roundIndex;\n\n\t\t// UI\n\t\troundNumber.Text().text = $\"Round {roundIndex+1}\";\n\t\thighScore.Text().text = $\"{Util.GInt(\"highScore\", 1)}\";\n\t\tif (Util.GBool(\"noads\", false)) {