earestBlock.gob, colorIndex, true);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (Input.GetMouseButtonUp(0))\n\t\t\tDropItem();\n\t}\n\tvoid DropItem() {\n\t\tv2 dropPos = (v2)ui2WorldPos(draggableItem);\n\t\tbool withinBoard = boardBounds.Contains(dropPos);\n\t\tif (withinBoard) {\n\t\t\t// apply item\n\t\t\tstring[] item = dockItems[dockSlots.IndexOf(activeDockSlot)].Split('_');\n\t\t\tstring itemType = item[0];\n\t\t\tif (itemType == \"bucket\") {\n\t\t\t\tint colorIndex = Array.IndexOf(colorNames, item[1]);\n\t\t\t\tBlock nearestBlock = blocks.OrderBy(b => {\n\t\t\t\t\treturn v2.Distance(b.gob.Pos(), dropPos);\n\t\t\t\t}).First();\n\t\t\t\tBucketFill(nearestBlock.gob, colorIndex);\n\t\t\t}\n\t\t\telse if (itemType == \"bomb\") {\n\t\t\t\tfloat radius = draggableItem.Child(\"radius\").transform.localScale.x * 0.5f;\n\t\t\t\tList<Block> blocksInLastGroup = GetBlocksInGroup(lastGroup);\n\t\t\t\tList<Block> blocksInRadius = blocks.Where(b => {\n\t\t\t\t\treturn v2.Distance(b.gob.Pos(), dropPos) <= radius\n\t\t\t\t\t\t&& !blocksInLastGroup.Contains(b)\n\t\t\t\t\t\t/*b.colorIndex == 0 &&*/\n\t\t\t\t\t\t;\n\t\t\t\t}).ToList();\n\t\t\t\tblocksInRadius.ForEach(b => {\n\t\t\t\t\tKillAdjacent(b.gob, b.gob.Pos());\n\t\t\t\t});\n\n\t\t\t\t// explosion force\n\t\t\t\tforeach (Gob group in groups) {\n\t\t\t\t\tif (group != lastGroup) {\n\t\t\t\t\t\tfloat dist = ((v2)group.Pos()-dropPos).magnitude;\n\t\t\t\t\t\tv2 dir = ((v2)group.Pos()-dropPos+v2.up).normalized;\n\t\t\t\t\t\tgroup.Body2D().AddForce(dir * 300f, ForceMode2D.Impulse);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tdraggableItem.Off();\n\n\t\t\t// save\n\t\t\tdockItems[dockSlots.IndexOf(activeDockSlot)] = \"_\";\n\t\t\tSaveDock();\n\t\t}\n\t\telse {\n\t\t\t// back to dock\n\t\t\tGob slot = activeDockSlot;\n\t\t\tv3 start = draggableItem.Pos();\n\t\t\tv3 stop = slot.Pos();\n\t\t\tDo(0f, 1f, 0.2f, Motion.COS,\n\t\t\tt => {\n\t\t\t\tdraggableItem.Pos(Lerp(start, stop, t));\n\t\t\t\tdraggableItem.transform.localScale = Lerp(v3.one, v3.one*0.6f, t);\n\t\t\t},\n\t\t\t() => {\n\t\t\t\tdraggableItem.Off();\n\t\t\t\tslot.Child(\"item\").On();\n\t\t\t});\n\t\t}\n\t\tdraggingItem = false;\n\t\tactiveDockSlot = null;\n\t}\n\tvoid VLerpCam() {\n\t\tif (paused)\n\t\t\tcam.gameObject.Pos(Lerp(cam.gameObject.Pos(), initialCamPos, 0.5f));\n\t\telse {\n\t\t\tv3[] sliderCorners = new v3[4];\n\t\t\tscoreSlider.gameObject.gc<RectTransform>().GetWorldCorners(sliderCorners);\n\t\t\tv3[] canvasCorners = new v3[4];\n\t\t\tcanvas.gameObject.gc<RectTransform>().GetWorldCorners(canvasCorners);\n\t\t\tfloat headerHeight = canvasCorners[1].y-sliderCorners[0].y;\n\t\t\tfloat screenHeight = canvasCorners[1].y-canvasCorners[0].y;\n\t\t\t\n\t\t\tfloat maxY = max(lastGroupMaxY, GetMaxGroupY(true));\n\t\t\tv3 camPos = cam.gameObject.Pos();\n\t\t\tv3 toPos = camPos; toPos.y = maxY-(screenHeight*0.5f-headerHeight);\n\t\t\tv3 zeroPos = camPos; zeroPos.y = 0f;\n\t\t\tif (toPos.y > 0f)\n\t\t\t\tcam.gameObject.Pos(Lerp(camPos, toPos, 0.05f));\n\t\t\telse\n\t\t\t\tcam.gameObject.Pos(Lerp(camPos, zeroPos, 0.1f));\n\t\t}\n\t}\n\tvoid Simulate() {\n\t\tfloat lastGroupX = lastGroup != null ? lastGroup.Pos().x : 0f;\n\t\t\n\t\t// float next group over highest dropped group\n\t\tif (lastGroup != null) {\n\t\t\tBounds groupBounds = GetGroupBounds(lastGroup);\n\t\t\tfloat maxGroupY = GetMaxGroupY();\n\t\t\tfloat vbuf = 0.5f;\n\t\t\tfloat topY = max(board.Pos().y+boardBounds.extents.y, maxGroupY);\n\t\t\tdropY = topY + groupBounds.extents.y + vbuf;\n\t\t}\n\n\t\t// drag next group\n\t\tif (Input.GetMouseButton(0) && !draggingItem && !hitUI) {\n\t\t\tif (lastGroup != null) {\n\t\t\t\tvar hit = Raycast(cam.ScreenPointToRay(Input.mousePosition), 100f, 6);\n\t\t\t\tif (hit != null)\n\t\t\t\t\tlastGroupX = hit.point.x;\n\t\t\t}\n\t\t}\n\n\t\t// position next group\n\t\tif (lastGroup != null) {\n\t\t\tPositionNextGroup(lastGroupX);\n\t\t}\n\n\t\t// drop next group\n\t\tif (Input.GetMouseButtonUp(0) && !draggingItem && !hitUI) {\n\t\t\tif (lastGro