// react
import {useState, useCallback, useEffect, useRef, useMemo, useContext} from 'react'

// fontawesome
import {faXmark,faArrowUpRightFromSquare,faArrowRotateLeft,faCompress,faExpand,faDownload,faSquareMinus,faSquarePlus,faTable,faCode,faStop,faArrowsRotate,faPlus,faMinus,faAngleRight,faAngleDown, faTv} from '@fortawesome/free-solid-svg-icons'

// custom
import './App.css'

// util
import * as util from './Util.js'
Object.assign(global, util)

const fullscreenWrap = (content, aspectRatio) => {
  return (
    <div
      id='fullscreen-container'
      style={{
        position: 'fixed',
        zIndex: 100,
        left: 50,
        right: 50,
        bottom: 50,
        top: 50,
        // background: 'rgba(255,255,0,0.2)',
        overflow: 'auto',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
      }}
    >
      <div
        id='fullscreen-container1'
        style={{
          height: '100%',
          aspectRatio: aspectRatio,
          maxWidth: '100%',
          // background: 'rgba(0,255,0,0.2)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        <div
          id='fullscreen-container2'
          style={{
            width: '100%',
            aspectRatio: aspectRatio,
            // background: 'rgba(0,0,255,0.2)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            overflow: 'hidden',
          }}
        >
          {content}
        </div>
      </div>
    </div>
  )
}

export default function Win({id=null, title, addTools, content, baseDim=null, minimizable=true, highlight=null, evaluating=false, evaluatingTooltip='Loading...', winref=null, bodyref=null, winbodystyle={}}) {
  if (id == null) id = title

  // util
  const key = (attr) => `Win_${title}_${attr}`
  
  // global
  const {fullscreenWin} = useContext(GlobalContext)

  // state
  const bodyref1 = bodyref == null ? useRef(null)
                                   : bodyref
  const winref1 = winref == null ? useRef(null)
                                 : winref
  const minimized = useStore(key('minimized'), false)
  const [hover, setHover] = useState(false)
  const fullscreend = fullscreenWin?.val == winref1

  // tool callbacks
  const onMinimize = useCallback(() => minimized.set(!minimized.val), 
    [minimized.val])
  const onFullscreen = useCallback(() => {
    const val = fullscreenWin.val == winref1 ? null
                                             : winref1
    fullscreenWin.set(val)
  }, [fullscreenWin.val])
  const onFullFullscreen = useCallback(() => {
    if (bodyref1.current != null) {
      bodyref1.current.requestFullscreen()
    }
  }, [fullscreenWin.val])

  const tools = {
    minimize:   toolButton({
                  id: 'minimize',
                  title: minimized.val ? 'Show' : 'Hide',
                  icon:  minimized.val ? faAngleRight : faAngleDown,
                  click: onMinimize,
                }),
    evaling:    toolButton({
                  id: 'evaling',
                  title: evaluatingTooltip,
                  icon:  faArrowsRotate,
                  iconClass: 'spin',
                }),
    fullscreen:    toolButton({
                  id: 'fullscreen',
                  title: fullscreend ? 'Close' : 'Popout',
                  icon:  fullscreend ? faXmark : faArrowUpRightFromSquare,
                  click: onFullscreen,
                }),
    fullfullscreen:    toolButton({
                  id: 'fullfullscreen',
                  title: 'Fullscreen',
                  icon:  faTv,
                  click: onFullFullscreen,
                }),
  }
  
  const overlayStyle = winref1.current != null ? {
    width: winref1.current.clientWidth,
    height: winref1.current.clientHeight,
    marginTop: -winref1.current.clientHeight,
  } : {}

  const basicFullscreen = fullscreend && baseDim == null
  const fittedFullscreen = fullscreend && baseDim != null
  const rootStyle = (
    basicFullscreen ? {
      position: 'fixed',
      zIndex: '100',
      inset: '50px',
    } :
    fittedFullscreen ? {
      width: '100%',
      height: '100%',
    } :
    {
      alignSelf: 'flex-start',
    }
  )

  // var rootStyle = {}
  if (fullscreend) {
    // rootStyle = {
    //   width: '100%',
    //   height: '100%',

    //   // position: 'fixed',

    //   // zIndex: 100,
    //   // left: 0,
    //   // right: 0,
    //   // top: 0,
    //   // bottom: 0,
    // }

    // if (baseDim == null) {
    //   rootStyle = {
    //     position: 'fixed',
    //     zIndex: 100,
    //     left: 50,
    //     right: 50,
    //     top: 50,
    //     bottom: 50,
    //   }
    // }
    // else {
    //   const vh = window.innerHeight
    //   const vw = window.innerWidth
    //   const tbh = 22
    //   const basew = baseDim.w
    //   const baseh = baseDim.h
    //   var mx = 50
    //   var my = 50
    //   {
    //     var bw = vw - 2*mx
    //     var bh = bw * (baseh/basew)
    //     if (bh < vh && bw < vw) {
    //       mx = 50
    //       my = (vh - bh - tbh) / 2
    //     }
    //   }
    //   {
    //     var bh = vh - 2*my - tbh
    //     var bw = bh * (basew/baseh)
    //     if (bh < vh && bw < vw) {
    //       mx = (vw - bw) / 2
    //       my = 50
    //     }
    //   }

    //   rootStyle = {
    //     position: 'fixed',
    //     zIndex: 100,
    //     left: mx,
    //     right: mx,
    //     top: my,
    //     bottom: my,
    //   }
    // }
  }

  // const rootStyle = fullscreend ? {
  //     position: 'fixed',
  //     zIndex: 100,
  //     left: 50,
  //     right: 50,
  //     top: 50,
  //     bottom: 50,
  //     // aspectRatio: 1/1,
  // } : {}
  const titleStyle = fullscreend ? {
    paddingLeft: '4px',
    paddingRight: '4px',
  } : {
    paddingRight: '6px',
  }
  const bodyStyle = (
    basicFullscreen ? {
      ...winbodystyle,
      // height: '-moz-calc(100% - 22px)',
      // height: '-webkit-calc(100% - 22px)',
      // height: '-o-calc(100% - 22px)',
      // height: 'calc(100% - 22px)',
      height: '100%',
    } :
    fittedFullscreen ? {
      // ...winbodystyle,
      // width: '100%',
      // height: '100%',
    } : {
      ...winbodystyle,
      overflow: 'hidden',
    }
  )

  
  fullscreend ? {
    // position: 'fixed',
    // width: '100%',
    // height: '100%',
    ...winbodystyle,
    // height: 'calc(100% - 22px)',
  } : {
    ...winbodystyle,
    overflow: 'hidden',
  }

  const win = (
    <div
      id={`window_${id}`}
      ref={winref1}
      className={`window ${highlight?.val ? 'highlight' : ''} ${fullscreend ? 'fullscreen' : ''}`}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={rootStyle}
    >
      <div className={`titlebar ${minimized.val ? 'minimized' : ''} ${highlight?.val ? 'highlight' : ''}`}>
        {minimizable && !fullscreend &&
          tools.minimize}
        <span className='title' style={titleStyle}>{title}</span>
        {evaluating ?
          tools.evaling
          : ((hover || fullscreend) && !minimized.val &&
            <div className='toolrow'>
              {addTools}
              {tools.fullscreen}
              {/* {tools.fullfullscreen} */}
            </div>)
        }
        {/* {tools.fullscreen} */}
      </div>
      <div ref={bodyref1} className='windowBody' style={bodyStyle}>
        {!minimized.val &&
          content}
      </div>
      {highlight?.val && 
        <div className='overlay' style={overlayStyle} />}
    </div>
  )

  const wrappedWin = fittedFullscreen ? fullscreenWrap(win, baseDim.w/(baseDim.h+22))
                                      : win
  return wrappedWin
}
